package com.bank.runbal.service;

import java.math.BigDecimal;
import java.util.logging.Logger;

// Tabulation: fill the closing-balance table bottom-up from the opening balance.
public class RunningBalanceService {
    private static final Logger log = Logger.getLogger(RunningBalanceService.class.getName());

    public BigDecimal[] closingBalances(BigDecimal opening, BigDecimal[] dailyNet) {
        int days = dailyNet.length;
        BigDecimal[] dp = new BigDecimal[days + 1];        // dp[0] is the base case
        dp[0] = opening;                                   // base: opening balance
        for (int i = 1; i <= days; i++) {
            dp[i] = dp[i - 1].add(dailyNet[i - 1]);        // depends on already-filled dp[i-1]
        }
        log.info(() -> "Final closing balance = " + dp[days]);
        return dp;
    }
}
