package com.bank.runbal;

import com.bank.runbal.service.RunningBalanceService;
import java.math.BigDecimal;
import java.util.Arrays;
import java.util.logging.Logger;

public class RunningBalanceApplication {
    private static final Logger log = Logger.getLogger(RunningBalanceApplication.class.getName());

    public static void main(String[] args) {
        RunningBalanceService service = new RunningBalanceService();
        BigDecimal opening = new BigDecimal("1000000");    // Rajesh SAV2001 opening
        BigDecimal[] dailyNet = {
            new BigDecimal("50000"), new BigDecimal("-20000"), new BigDecimal("-5000")
        };
        BigDecimal[] balances = service.closingBalances(opening, dailyNet);
        log.info(() -> "Closing balances table = " + Arrays.toString(balances));
    }
}
